import torch

def run(tokens, experts, gate):
    probs = torch.softmax(gate.float(), dim=-1)
    weights, ids = torch.topk(probs, k=min(1, probs.shape[-1]), dim=-1)
    out = torch.zeros(tokens.shape[0], experts.shape[-1], dtype=torch.float32, device=tokens.device)
    for choice in range(ids.shape[-1]):
        selected = experts.float()[ids[:, choice]]
        projected = torch.bmm(tokens.float().unsqueeze(1), selected).squeeze(1)
        out = out + projected * weights[:, choice:choice + 1]
    return (out).to(torch.bfloat16)
